def eulerian_num(n, m):
    # Initialize the result to 0
    result = 0
    # Loop through k from 0 to n
    for k in range(n + 1):
        # Calculate the binomial coefficient
        binomial = binomial_coefficient(n, k)
        # Calculate the result using the formula for Eulerian numbers
        result += (-1) ** k * binomial * m ** (n - k)
    # Return the result divided by n factorial
