def max_product(nums):
    from functools import lru_cache

    # Define a helper function to calculate the maximum product
    @lru_cache(maxsize=None)
    def helper(index, prev):
        if index == len(nums):
            return 1
        product = 1
        for i in range(index, len(nums):
            if nums[i] > prev:
                product = max(product, nums[i] * helper(i + 1, nums[i]))
        return product

    # Calculate the maximum product
    return max(helper(0, 0))

